12|import { AmbienceController } from "./ambience-controller";
13|import { WebAmbienceEngine } from "./ambience-engine";
14|
15|const RAIN = AMBIENCES[0]!;
16|
17|const DROPS: Record<string, Array<[number, number]>> = {
18|  drizzle: [
19|    [7.5, 14.2],
20|    [10, 14.2],
21|    [12.5, 14.2],
22|  ],
23|  moderate: [
24|    [6.5, 13.8],
25|    [10, 13.8],
26|    [13.5, 13.8],
27|    [6.5, 15.9],
28|    [10, 15.9],
29|    [13.5, 15.9],
30|  ],
31|  storm: [
32|    [6, 14],
33|    [8, 14],
34|    [13.5, 14],
35|    [15.5, 14],
36|    [6, 16.2],
37|  ],
38|};
39|
40|// The button owns its controller: it loads prefs once, saves on change,
41|// and starts the stored level on the first gesture anywhere in the page.
42|export function RainAmbience({ muted }: { muted: boolean }) {
43|  const controllerRef = useRef<AmbienceController | null>(null);
44|  const [level, setLevel] = useState("off");
45|  const [volume, setVolume] = useState(DEFAULT_AMBIENCE_VOLUME);
46|
47|  useEffect(() => {
48|    const controller = new AmbienceController(new WebAmbienceEngine());
49|    controllerRef.current = controller;
50|    const prefs = loadAmbiencePrefs();
51|    if (prefs) {
52|      controller.setVolume(prefs.volume);
53|      setVolume(prefs.volume);
54|      if (prefs.level !== "off" && levelById(RAIN, prefs.level)) {
55|        controller.setLevel(prefs.level);
56|        setLevel(prefs.level);
57|      }
58|    }
59|    const unlock = () => void controller.unlock();
60|    document.addEventListener("pointerdown", unlock, { once: true });
61|    document.addEventListener("keydown", unlock, { once: true });
62|    return () => {
63|      document.removeEventListener("pointerdown", unlock);
64|      document.removeEventListener("keydown", unlock);
65|      controller.dispose();
66|      controllerRef.current = null;
67|    };
68|  }, []);
69|
70|  useEffect(() => {
71|    controllerRef.current?.setMuted(muted);
72|  }, [muted]);
73|
74|  function cycle() {
75|    const controller = controllerRef.current;
76|    if (!controller) return;
77|    void controller.unlock();
78|    const id = nextLevel(RAIN, level);
79|    controller.setLevel(id);
80|    setLevel(id);
81|    saveAmbiencePrefs({ level: id, volume });
82|  }
83|
84|  function changeVolume(value: number) {
85|    controllerRef.current?.setVolume(value);
86|    setVolume(value);
87|    saveAmbiencePrefs({ level, volume: value });
88|  }
89|
90|  const label = ambienceLabel(RAIN, level);
91|  return (
92|    <>
93|      <button
94|        type="button"
95|        className="skip rain"
96|        data-level={level}
97|        onClick={cycle}
98|        aria-label={label}
99|        title={label}
100|      >
101|        <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
102|          <path
103|            className="rain-cloud"
104|            d="M14.5 12.2h-8.3a3.4 3.4 0 0 1-.6-6.7 4.6 4.6 0 0 1 9-1.1 3 3 0 0 1-.1 7.8z"
105|            strokeLinejoin="round"
106|          />
107|          {(DROPS[level] ?? []).map(([x, y], i) => (
108|            <line
109|              key={i}
110|              className="rain-drop"
111|              x1={x}
112|              y1={y}
113|              x2={x}
114|              y2={y + (level === "drizzle" ? 1.8 : 1.5)}
115|            />
116|          ))}
117|          {level === "storm" ? (
118|            <polygon
119|              className="rain-bolt"
120|              points="11.3,13.4 9.3,16.2 10.6,16.2 10,18.8 12.5,15.6 11.2,15.6"
121|              fill="#f2c230"
122|              stroke="none"
123|            />
124|          ) : null}
125|        </svg>
126|      </button>
127|      {level !== "off" ? (
128|        <input
129|          type="range"
130|          className="rain-volume"
131|          min={0}
132|          max={1}
133|          step={0.05}
134|          value={volume}
135|          onChange={(e) => changeVolume(Number(e.target.value))}
136|          aria-label="Rain volume"
137|        />
138|      ) : null}
139|    </>
140|  );
